270: void ThreadUtility::addPeriodicTask(const LogString& name, std::function<void()> f, const Period& delay)
271: {
272: 	if (!m_priv->log)
273: 		m_priv->log = Logger::getLogger("ThreadUtility");
274: 	LOGLOG_DEBUG(m_priv->log, LOG4CXX_STR("addPeriodicTask: ") << name);
275: 	std::lock_guard<std::recursive_mutex> lock(m_priv->job_mutex);
276: 	if (m_priv->maxDelay < delay)
277: 		m_priv->maxDelay = delay;
278: 	auto currentTime = std::chrono::system_clock::now();
279: 	m_priv->jobs.push_back( priv_data::NamedPeriodicFunction{name, delay, currentTime + delay, f, 0, false} );
280: 
281: 	// Restart thread if it has stopped.
282: 	if (!m_priv->threadIsActive.load() && m_priv->thread.joinable())
283: 		m_priv->thread.join();
284: 
285: 	if (!m_priv->thread.joinable())
286: 	{
287: 		m_priv->terminated.store(false);
288: 		m_priv->threadIsActive.store(true);
289: 		m_priv->thread = createThread(LOG4CXX_STR("log4cxx"), [this]()
290: 			{
291: 				LOGLOG_DEBUG(m_priv->log, "doPeriodicTasks: " << "started");
292: 				m_priv->doPeriodicTasks();
293: 				LOGLOG_DEBUG(m_priv->log, "doPeriodicTasks: " << "stopped");
294: 				m_priv->threadIsActive.store(false);
295: 			});
296: 	}
297: 	else
298: 		m_priv->interrupt.notify_one();
299: }
